function applyTextNutrition(data){
 if(modal?.type!=='custom-food'||!$('#custom-food-form'))throw Error('Bitte zuerst ein eigenes Produkt öffnen.');
 const n=Object.fromEntries(KEYS.map(k=>[k,data.n[k]??null]));
 const candidate={id:modal.food?.id||'text-preview',name:$('#custom-name').value.trim()||'Textvorschau',basis:data.basis,n,q:data.q||{},density:null};
 C.validateFood(candidate,KEYS);
 if(data.basis==='g'&&['protein','fat','carbs','fiber','sugar','saturated','salt'].some(k=>n[k]!==null&&n[k]>100))throw Error('Mehr als 100 g eines Nährstoffs pro 100 g. Bitte Bezugsmenge und Ausgangswerte prüfen.');
 if(n.sugar!==null&&n.carbs!==null&&n.sugar>n.carbs+.5||n.saturated!==null&&n.fat!==null&&n.saturated>n.fat+.5)throw Error('Zucker bzw. gesättigtes Fett über dem Gesamtwert. Bitte die Tabellenspalte prüfen.');
 if(!KEYS.some(k=>n[k]!==null))throw Error('Keine bezifferten Werte gefunden.');
 const before={food:modal.food?copy(modal.food):null,basis:$('#custom-basis').value,values:Object.fromEntries(KEYS.map(k=>[k,$('#custom-'+k).value]))};
 for(const k of KEYS)$('#custom-'+k).value=n[k]===null?'':String(Number(n[k].toPrecision(12)));
 $('#custom-basis').value=data.basis;
 modal.food={...(modal.food||{}),q:copy(data.q||{}),source:'Nährwerttext · von mir geprüft · Ausgangswerte pro '+data.sourceAmount+' '+data.basis+'; auf 100 '+data.basis+' umgerechnet',sourceUrl:null};
 document.querySelectorAll('#custom-food-form input[type=checkbox][required]').forEach(e=>e.checked=false);
 $('#custom-basis').dispatchEvent(new Event('input',{bubbles:true}));
 return before;
}
function restoreTextNutrition(before){
 if(modal?.type!=='custom-food'||!$('#custom-food-form'))throw Error('Das ursprüngliche Produktformular ist nicht mehr geöffnet.');
 for(const k of KEYS)$('#custom-'+k).value=before.values[k];
 $('#custom-basis').value=before.basis;modal.food=before.food?copy(before.food):null;
 $('#custom-basis').dispatchEvent(new Event('input',{bubbles:true}));
}

readableLines(text){
 const labels='(?:Brennwert|Energie|Energy|Energia|davon\\s+ges[aä]ttigte(?:\\s+Fetts[aä]uren)?|ges[aä]ttigte\\s+Fetts[aä]uren|saturated\\s+fat|of\\s+which\\s+sugars|davon\\s+Zucker|Zucker|Nahrungsfasern|Ballaststoffe|Kohlenhydrate|Carbohydrates?|Eiwei(?:ss|ß)|Proteine?|Fett|Fat|Salz|Salt|Vitamin[ea]?\\s*[ABCDEK]\\s*\\d*|Calcium|Kalzium|Magnesium|Kalium|Natrium|Eisen|Zink|Jod|Selen|Biotin|Niacin|Pantothensäure|Folsäure|Folat)';
 const re=new RegExp('(^|[^\\p{L}\\p{N}])('+labels+')(?=$|[^\\p{L}\\p{N}])','gimu');
 return String(text).replace(/\r/g,'').replace(re,(_,gap,label)=>gap+'\n'+label).split('\n').map(x=>x.trim()).filter(Boolean);
}
